            };

            foreach (var g in games)
            {
                list.Add(new NintendoCatalogItem
                {
                    Title = g.Title,
                    Genre = g.Genre,
                    Year = g.Year,
                    Developer = g.Dev,
                    Publisher = g.Pub,
                    Region = g.Region,
                    Desc = g.Desc,
                    TitleId = g.TitleId,
                    Edition = g.Edition,
                    Version = g.Version
                });
            }

            return list;
        }
    }
}